-- 02 Catalog: areas, occupations and their policies (catalog/*.json), neighborhoods
-- (data/neighborhoods.json) and platform settings. Rows come from supabase/seed.sql,
-- generated by scripts/generate-seed.mjs.

create table public.areas (
  slug text primary key check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name text not null,
  description text,
  icon text,
  sort int not null default 0,
  created_at timestamptz not null default now()
);

create table public.occupations (
  slug text primary key check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  area_slug text not null references public.areas (slug) on update cascade,
  name text not null,
  synonyms text[] not null default '{}',
  created_at timestamptz not null default now()
);

create index occupations_area_slug_idx on public.occupations (area_slug);

create table public.occupation_policies (
  occupation_slug text primary key references public.occupations (slug) on update cascade on delete cascade,
  regulated boolean not null default false,
  regulator_body text not null default '',
  registry_name text not null default '',
  legal_basis text not null default '',
  verification public.verification_step[] not null default '{}',
  background_check boolean not null default false,
  billing public.billing_model not null default 'sob_consulta_juridica',
  rating_ranking boolean not null default false,
  labor_lock boolean not null default false,
  provider_type public.provider_kind not null default 'autonomo',
  audience_minors boolean not null default false,
  price_units public.price_unit[] not null default '{}',
  locations public.service_location[] not null default '{}',
  notes text not null default '',
  confidence text not null default 'a_confirmar' check (confidence in ('conferido', 'a_confirmar')),
  sources text[] not null default '{}',
  created_at timestamptz not null default now()
);

create table public.neighborhoods (
  id uuid primary key default gen_random_uuid(),
  city text not null default 'São Paulo',
  name text not null,
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  zone text,
  created_at timestamptz not null default now()
);

create table public.platform_settings (
  key text primary key,
  value jsonb not null,
  -- Internal keys are visible to admins only.
  internal boolean not null default false,
  updated_at timestamptz not null default now(),
  created_at timestamptz not null default now()
);

create trigger platform_settings_touch
  before update on public.platform_settings
  for each row execute function private.touch_updated_at();

-- Sensitive features start off: escrow and commission wait for legal advice.
insert into public.platform_settings (key, value) values
  ('commission_enabled', 'false'),
  ('commission_bps', '1200'),
  ('escrow_enabled', 'false'),
  ('pro_price_cents', '4900'),
  ('proposal_limit', '3'),
  ('labor_lock_days_per_week', '2')
on conflict (key) do nothing;

-- Typed readers used by rules; a missing or malformed key falls back to the default.
create function private.setting_int(p_key text, p_default int)
returns int
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select case when jsonb_typeof(s.value) = 'number' then (s.value #>> '{}')::int end
       from public.platform_settings s where s.key = p_key),
    p_default
  );
$$;

create function private.setting_bool(p_key text, p_default boolean)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select case when jsonb_typeof(s.value) = 'boolean' then (s.value #>> '{}')::boolean end
       from public.platform_settings s where s.key = p_key),
    p_default
  );
$$;

-- ---------------------------------------------------------------------------
-- RLS: public read, admin write
-- ---------------------------------------------------------------------------

alter table public.areas enable row level security;
alter table public.occupations enable row level security;
alter table public.occupation_policies enable row level security;
alter table public.neighborhoods enable row level security;
alter table public.platform_settings enable row level security;

create policy areas_read on public.areas for select to anon, authenticated using (true);
create policy areas_admin_insert on public.areas for insert to authenticated with check ((select public.is_admin()));
create policy areas_admin_update on public.areas for update to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
create policy areas_admin_delete on public.areas for delete to authenticated using ((select public.is_admin()));

create policy occupations_read on public.occupations for select to anon, authenticated using (true);
create policy occupations_admin_insert on public.occupations for insert to authenticated with check ((select public.is_admin()));
create policy occupations_admin_update on public.occupations for update to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
create policy occupations_admin_delete on public.occupations for delete to authenticated using ((select public.is_admin()));

create policy occupation_policies_read on public.occupation_policies for select to anon, authenticated using (true);
create policy occupation_policies_admin_insert on public.occupation_policies for insert to authenticated
  with check ((select public.is_admin()));
create policy occupation_policies_admin_update on public.occupation_policies for update to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
create policy occupation_policies_admin_delete on public.occupation_policies for delete to authenticated
  using ((select public.is_admin()));

create policy neighborhoods_read on public.neighborhoods for select to anon, authenticated using (true);
create policy neighborhoods_admin_insert on public.neighborhoods for insert to authenticated with check ((select public.is_admin()));
create policy neighborhoods_admin_update on public.neighborhoods for update to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
create policy neighborhoods_admin_delete on public.neighborhoods for delete to authenticated using ((select public.is_admin()));

create policy platform_settings_read_public on public.platform_settings
  for select to anon, authenticated using (not internal);
create policy platform_settings_admin_read on public.platform_settings
  for select to authenticated using ((select public.is_admin()));
create policy platform_settings_admin_insert on public.platform_settings
  for insert to authenticated with check ((select public.is_admin()));
create policy platform_settings_admin_update on public.platform_settings
  for update to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy platform_settings_admin_delete on public.platform_settings
  for delete to authenticated using ((select public.is_admin()));

grant select on public.areas, public.occupations, public.occupation_policies, public.neighborhoods,
  public.platform_settings to anon, authenticated;
grant insert, update, delete on public.areas, public.occupations, public.occupation_policies,
  public.neighborhoods, public.platform_settings to authenticated;

revoke all on all functions in schema private from public;
